submitted_code:
def solve_27_788(input_data: str) -> str:
    # 접근: Hashing, Tree, Backtracking (초안)  #698
    data = list(map(int, input_data.strip().split()))
    if not data:
        return ""
    n = data[0]
    arr = data[1:1+n]
    # TODO: 정확한 점화식/자료구조는 보완 필요
    s = 0
    for x in arr:
        s += x
    return str(s)

