from collections import deque

def solve_10039_226(input_data: str) -> str:
    # 핵심: HashMap, Join, Sorting  (구현 완료, 예외처리 일부 보완 필요) #424
    it = list(map(int, input_data.strip().split()))
    if not it:
        return ""
    n = it[0]
    arr = it[1:1+n]
    # 예시: DP or Greedy 기반 누적 계산 (문제별로 해석 필요)
    dp = [0]*(n+1)
    for i in range(1, n+1):
        dp[i] = dp[i-1] + arr[i-1]
    return str(dp[n])

